// Logo de Doctormás incrustado en base64 para que aparezca en TODO documento
// generado (recibos, informes, comprobantes) sin depender de una ruta de
// archivo — los PDF se renderizan desde un data: URL sin baseURL (ver
// electron/pdf.js), así que una ruta relativa a la imagen no cargaría.
// Es el logo horizontal (ícono + wordmark, fondo transparente, sin la
// leyenda "centro de atención médica inmediata" ni el RIF — eso ya se
// muestra aparte como texto en cada documento vía empresaConRif()).
export const LOGO_DATA_URI = 'data:image/png;base64,';

export function logoHeaderHTML(alturaPx) {
  alturaPx = alturaPx || 42;
  return `<img src="${LOGO_DATA_URI}" alt="Doctormás" style="height:${alturaPx}px;display:block;margin-bottom:10px;">`;
}
